// Aviso diario: se manda todos los dias a las 12:00 (misma hora).
// El limite arranca en el ultimo numero del registro anterior: no se reinicia el historial.
const TZ = 'America/Argentina/Buenos_Aires';
const NUMERO_BASE = 16;  // ultimo aviso del registro anterior (2026-11-18, numero 16)
const TOTAL_NUEVOS = 90; // avisos nuevos que se pueden mandar a partir de NUMERO_BASE
const LIMITE = NUMERO_BASE + TOTAL_NUEVOS;

const esFecha = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const label = (s) => s.slice(8, 10) + '/' + s.slice(5, 7) + '/' + s.slice(0, 4);

const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const p = {};
for (const x of fmt.formatToParts(new Date())) { p[x.type] = x.value; }
const hoy = p.year + '-' + p.month + '-' + p.day;

const filas = $input.all().map((i) => i.json).filter((r) => r && esFecha(r.fecha));
const numeros = filas.map((r) => Number(r.numero) || 0);
const ultimoNumero = numeros.length > 0 ? Math.max(...numeros) : 0;
const base = Math.max(NUMERO_BASE, ultimoNumero);
const proximo = base + 1;
const yaHayAvisoHoy = filas.some((r) => String(r.fecha) === hoy);

let tipo = 'nada';
let motivo = '';
if (yaHayAvisoHoy) {
  motivo = 'el aviso de hoy ya se mando';
} else if (proximo > LIMITE) {
  motivo = 'ciclo terminado (limite ' + LIMITE + ')';
} else {
  tipo = 'aviso';
  motivo = 'toca el aviso del dia';
}

return [{ json: {
  tipo: tipo,
  motivo: motivo,
  hoy: hoy,
  fecha: hoy,
  fechaAviso: hoy,
  fechaAvisoLabel: label(hoy),
  numeroAviso: tipo === 'aviso' ? proximo : 0,
  indice: tipo === 'aviso' ? proximo - 1 : 0,
  limite: LIMITE,
  ultimoNumero: ultimoNumero,
  avisosEnviados: filas.length
} }];

