// Limpieza: unos minutos antes del aviso nuevo, borra del chat los mensajes de dias anteriores.
// Borra el aviso (message_id) y TAMBIEN su recordatorio de olvido (aviso_final_message_id):
// en el chat tiene que quedar solo el dia de hoy (uno por dia, sin acumularse).
// Telegram solo permite borrar mensajes de menos de 48 h: se borran los de 1 o 2 dias.
const TZ = 'America/Argentina/Buenos_Aires';
const MAX_EDAD_DIAS = 2;

// Chequeo de fecha sin expresiones regulares (evita problemas de escape).
const esDigito = (c) => c >= '0' && c <= '9';
const esFecha = (s) => {
  const t = String(s);
  if (t.length !== 10 || t[4] !== '-' || t[7] !== '-') return false;
  for (let i = 0; i < 10; i = i + 1) {
    if (i === 4 || i === 7) continue;
    if (!esDigito(t[i])) return false;
  }
  return true;
};
const aUTC = (s) => Date.UTC(Number(String(s).slice(0, 4)), Number(String(s).slice(5, 7)) - 1, Number(String(s).slice(8, 10)));
const dias = (a, b) => Math.round((aUTC(a) - aUTC(b)) / 86400000);
const esTrue = (v) => v === true || ['true', '1'].includes(String(v).toLowerCase());

const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const p = {};
for (const x of fmt.formatToParts(new Date())) { p[x.type] = x.value; }
const hoy = p.year + '-' + p.month + '-' + p.day;

const salida = [];
for (const r of $input.all().map((i) => i.json)) {
  const fecha = String(r.fecha || '');
  if (!esFecha(fecha)) continue;
  const edad = dias(hoy, fecha);
  if (edad < 1 || edad > MAX_EDAD_DIAS) continue;

  const avisoId = Number(r.message_id) || 0;
  if (avisoId > 0 && !esTrue(r.borrado)) {
    salida.push({ json: { fecha: fecha, message_id: avisoId, campo: 'borrado' } });
  }

  const olvidoId = Number(r.aviso_final_message_id) || 0;
  if (olvidoId > 0 && !esTrue(r.aviso_final_borrado)) {
    salida.push({ json: { fecha: fecha, message_id: olvidoId, campo: 'aviso_final' } });
  }
}
return salida;

const esFecha = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const aUTC = (s) => Date.UTC(Number(String(s).slice(0, 4)), Number(String(s).slice(5, 7)) - 1, Number(String(s).slice(8, 10)));

const filas = $input.all().map(i => i.json).filter(r => r && esFecha(r.fecha));
filas.sort((x, y) => aUTC(x.fecha) - aUTC(y.fecha));

const out = [];
for (let i = 0; i < filas.length; i = i + 1) {
  const r = filas[i];
  const numero = Number(r.numero) > 0 ? Number(r.numero) : (i + 1);
  out.push({ json: {
    fecha: String(r.fecha),
    numero_aviso: numero,
    estado: r.estado === 'confirmado' ? 'confirmado' : 'pendiente',
    confirmado_at: String(r.confirmado_at || ''),
    aviso_final_enviado: r.aviso_final === true ? 'si' : 'no',
    mensaje_en_chat: String(r.borrado) === 'true' ? 'no' : 'si',
    message_id: Number(r.message_id || 0),
    aviso_final_message_id: Number(r.aviso_final_message_id || 0)
  }});
}
return out;

const SECRET = 'a7f3c9e2b1d8465f0a3c';
const q = $input.first().json.query || {};
const fecha = String(q.f || '');
const ok = String(q.s || '') === SECRET && fecha.length === 10;
return [{ json: { ok, fecha } }];

// Recordatorio: 2 horas despues del aviso de las 12:00 (14:00), si sigue sin confirmar.
// Si la pastilla ya se confirmo antes de las 14:00, este nodo devuelve 'nada' y no se manda nada.
// El mensaje lleva el mismo boton que el aviso y se borra cuando confirmas.
const TZ = 'America/Argentina/Buenos_Aires';
const HORAS_MINIMAS = 1.5; // normalmente son 2 h (12:00 -> 14:00); el margen cubre corridas demoradas

// Chequeo de fecha sin expresiones regulares (evita problemas de escape).
const esFecha = (s) => {
  const t = String(s);
  if (t.length !== 10 || t[4] !== '-' || t[7] !== '-') return false;
  for (let i = 0; i < 10; i = i + 1) {
    if (i === 4 || i === 7) continue;
    const c = t[i];
    if (c < '0' || c > '9') return false;
  }
  return true;
};
const label = (s) => s.slice(8, 10) + '/' + s.slice(5, 7) + '/' + s.slice(0, 4);
const aMs = (v) => { const t = new Date(String(v || '')).getTime(); return Number.isFinite(t) ? t : null; };
const esTrue = (v) => v === true || ['true', '1'].includes(String(v).toLowerCase());

const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const p = {};
for (const x of fmt.formatToParts(new Date())) { p[x.type] = x.value; }
const hoy = p.year + '-' + p.month + '-' + p.day;

const filas = $input.all().map((i) => i.json).filter((r) => r && esFecha(r.fecha));
const deHoy = filas.find((r) => String(r.fecha) === hoy);

let tipo = 'nada';
let motivo = '';
let horas = null;
if (!deHoy) {
  motivo = 'hoy no se mando aviso';
} else if (String(deHoy.estado) !== 'pendiente') {
  motivo = 'la pastilla ya estaba confirmada';
} else if (esTrue(deHoy.aviso_final)) {
  motivo = 'el recordatorio ya se mando';
} else {
  const enviado = aMs(deHoy.createdAt) || aMs(deHoy.updatedAt);
  horas = enviado ? Math.round(((Date.now() - enviado) / 3600000) * 10) / 10 : 99;
  if (horas >= HORAS_MINIMAS) { tipo = 'final'; motivo = 'pasaron ' + horas + ' h sin confirmar'; }
  else { motivo = 'todavia no pasaron las horas minimas (' + horas + ' h)'; }
}

return [{ json: {
  tipo: tipo,
  motivo: motivo,
  hoy: hoy,
  fecha: hoy,
  fechaLabel: label(hoy),
  numeroAviso: deHoy ? (Number(deHoy.numero) || 0) : 0,
  horasDesdeElAviso: horas
} }];
